CREATE TABLE IF NOT EXISTS park_status_snapshots(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,resource_ref TEXT NOT NULL,status TEXT NOT NULL,status_as_of TIMESTAMPTZ NOT NULL,official BOOLEAN NOT NULL,safety_message TEXT,source_reference TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS guidance_requests(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,user_id BIGINT NOT NULL,location_cell TEXT,location_expires_at TIMESTAMPTZ,accessibility_needs JSONB NOT NULL DEFAULT '[]'::jsonb,language TEXT NOT NULL,mode TEXT NOT NULL,guidance JSONB NOT NULL,manual_help_required BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS park_incidents(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,incident_ref TEXT NOT NULL,severity TEXT NOT NULL,official_message TEXT NOT NULL,human_queue_status TEXT NOT NULL DEFAULT 'requested',created_by BIGINT NOT NULL,resolved_by BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,incident_ref));
CREATE TABLE IF NOT EXISTS park_integration_runs(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,provider TEXT NOT NULL,status TEXT NOT NULL,data_as_of TIMESTAMPTZ,error_code TEXT,error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK(status IN ('online','stale','offline','failed')));
CREATE TABLE IF NOT EXISTS park_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id TEXT NOT NULL,actor_user_id BIGINT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,details JSONB NOT NULL,request_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
